const t=["inicio","projetos","cadastro"];export function getCurrentRoute(){const e=new URLSearchParams(window.location.search),n=e.get("pagina"),o=e.get("projeto");return{pagina:t.includes(n)?n:"inicio",projeto:o}}export function navigate(e,n=null){if(!t.includes(e))return;const o=new URLSearchParams;o.set("pagina",e),n&&o.set("projeto",n);const a=`${window.location.pathname}?${o.toString()}`;window.history.pushState({pagina:e,projeto:n},"",a),window.dispatchEvent(new PopStateEvent("popstate"))}export function initRouter(t){document.addEventListener("click",t=>{const e=t.target.closest("a[data-route]");if(!e)return;t.preventDefault();navigate(e.dataset.route,new URL(e.href).searchParams.get("projeto"))}),window.addEventListener("popstate",()=>{t(getCurrentRoute())}),t(getCurrentRoute())}